// Builds the extension's generated files from the shared Sankalpa engine (single source of truth):
//   ../form-scanner/src/rules.js, engine/cases.js, engine/replay-core.js  → lib/shared/
//   ../form-scanner/src/engine/page.js + src/inpage-extra.js             → content/inpage.js (window.__sk)
//   src/main-world.js + replayInPage                                       → content/main.js  (window.__skCap / __skReplay)
// Run: node scripts/build.mjs
import { mkdirSync, copyFileSync, writeFileSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ext = join(dirname(fileURLToPath(import.meta.url)), '..');
const core = join(ext, '..', 'form-scanner', 'src');
const version = JSON.parse(readFileSync(join(ext, 'manifest.json'), 'utf8')).version;
const banner = '// GENERATED by scripts/build.mjs, do not edit. Edit form-scanner/src or sankalpa-extension/src instead.\n';

mkdirSync(join(ext, 'lib', 'shared', 'engine'), { recursive: true });
mkdirSync(join(ext, 'content'), { recursive: true });
for (const f of ['rules.js', 'engine/cases.js', 'engine/replay-core.js']) {
  writeFileSync(join(ext, 'lib', 'shared', f), banner + readFileSync(join(core, f), 'utf8'));
}
for (const f of ['fields-ui.js', 'report-md.js', 'ai.js', 'ai-ui.js', 'fun.js', 'fun-ui.js']) {
  writeFileSync(join(ext, 'lib', 'shared', f), banner + readFileSync(join(core, '..', 'public', f), 'utf8'));
}

const load = (p) => import(pathToFileURL(p).href);
const fns = (mod) => Object.entries(mod).filter(([, v]) => typeof v === 'function').map(([k, v]) => `  ${k}: ${v.toString()},`).join('\n');

const page = await load(join(core, 'engine', 'page.js'));
const extra = await load(join(ext, 'src', 'inpage-extra.js'));
writeFileSync(join(ext, 'content', 'inpage.js'), `${banner}(() => {
  if (window.__sk && window.__sk.__v === ${JSON.stringify(version)}) return;
  window.__sk = {
  __v: ${JSON.stringify(version)},
${fns(page)}
${fns(extra)}
  };
})();
`);

const main = await load(join(ext, 'src', 'main-world.js'));
const { replayInPage } = await load(join(core, 'engine', 'replay-core.js'));
writeFileSync(join(ext, 'content', 'main.js'), `${banner}(() => {
  if (window.__skCap) return;
  window.__skCap = {
${fns(main)}
  };
  const replayInPage = ${replayInPage.toString()};
  window.__skReplay = async (spec) => {
    window.__skReplaying = true; // replays are not recorded as captures
    try { return await replayInPage(spec); } finally { window.__skReplaying = false; }
  };
})();
`);
console.log(`Built Sankalpa extension ${version}: lib/shared/*, content/inpage.js, content/main.js`);
